export type ParsedCloseMissedInstruction<
  TProgram extends string = typeof FITR_VAULT_PROGRAM_ADDRESS,
  TAccountMetas extends readonly AccountMeta[] = readonly AccountMeta[],
> = {
  programAddress: Address<TProgram>;
  accounts: {
    cranker: TAccountMetas[0];
    pool: TAccountMetas[1];
    user: TAccountMetas[2];
    day: TAccountMetas[3];
    commitment: TAccountMetas[4];
    profile: TAccountMetas[5];
  };
  data: CloseMissedInstructionData;
};

export function parseCloseMissedInstruction<
  TProgram extends string,
  TAccountMetas extends readonly AccountMeta[],
>(
  instruction: Instruction<TProgram> &
    InstructionWithAccounts<TAccountMetas> &
    InstructionWithData<ReadonlyUint8Array>,
): ParsedCloseMissedInstruction<TProgram, TAccountMetas> {
  if (instruction.accounts.length < 6) {
    throw new SolanaError(
      SOLANA_ERROR__PROGRAM_CLIENTS__INSUFFICIENT_ACCOUNT_METAS,
      {
        actualAccountMetas: instruction.accounts.length,
        expectedAccountMetas: 6,
      },
    );
  }
  let accountIndex = 0;
  const getNextAccount = () => {
    const accountMeta = (instruction.accounts as TAccountMetas)[accountIndex]!;
    accountIndex += 1;
    return accountMeta;
  };
  return {
    programAddress: instruction.programAddress,
    accounts: {
      cranker: getNextAccount(),
      pool: getNextAccount(),
      user: getNextAccount(),
      day: getNextAccount(),
      commitment: getNextAccount(),
      profile: getNextAccount(),
    },
    data: getCloseMissedInstructionDataDecoder().decode(instruction.data),
  };
}
